"""Full connectivity test from all hosts."""
import concurrent.futures
from netmiko import ConnectHandler

HOSTS = {
    "B1-PC1": {"host": "192.168.122.31", "lab_ip": "10.1.1.10"},
    "B1-PC2": {"host": "192.168.122.32", "lab_ip": "10.1.1.11"},
    "B2-PC1": {"host": "192.168.122.33", "lab_ip": "10.1.2.10"},
