    "B3-PC1": {"host": "192.168.122.35", "lab_ip": "10.1.3.10"},
    "B3-PC2": {"host": "192.168.122.36", "lab_ip": "10.1.3.11"},
    "B4-PC1": {"host": "192.168.122.37", "lab_ip": "10.2.1.10"},
    "B4-PC2": {"host": "192.168.122.38", "lab_ip": "10.2.1.11"},
    "B4-PC3": {"host": "192.168.122.39", "lab_ip": "10.2.2.10"},
    "B4-PC4": {"host": "192.168.122.40", "lab_ip": "10.2.2.11"},
}

NON_GUEST = ["B1-PC1", "B1-PC2", "B2-PC1", "B2-PC2", "B3-PC1", "B3-PC2", "B4-PC1", "B4-PC2"]
GUEST = ["B4-PC3", "B4-PC4"]
INTERNET = ["8.8.8.8", "1.1.1.1"]

def ping_from(src_name, targets):
    """Ping a list of target IPs from src host. Returns dict of target->pass/fail."""
    conn = ConnectHandler(host=HOSTS[src_name]["host"], device_type="linux", username="root", password="alpine")
    results = {}
    for target_ip in targets:
        out = conn.send_command(f"ping -c 2 -W 3 {target_ip}", read_timeout=15)
        success = "bytes from" in out or "0% packet loss" in out
        results[target_ip] = success
    conn.disconnect()
    return src_name, results

# Build test plan
all_tests = {}
for src in HOSTS:
    targets = []
    # All hosts ping internet
    targets.extend(INTERNET)
    # Non-guest to non-guest
    if src in NON_GUEST:
        for dst in NON_GUEST:
            if dst != src:
                targets.append(HOSTS[dst]["lab_ip"])
        # Non-guest to guest (should FAIL)
        for dst in GUEST:
            targets.append(HOSTS[dst]["lab_ip"])
    # Guest to guest
    elif src in GUEST:
        for dst in GUEST:
            if dst != src:
                targets.append(HOSTS[dst]["lab_ip"])
        # Guest to non-guest (should FAIL)
        for dst in NON_GUEST:
            targets.append(HOSTS[dst]["lab_ip"])
    all_tests[src] = targets

results = {}
with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex:
    futures = {ex.submit(ping_from, src, targets): src for src, targets in all_tests.items()}
    for f in concurrent.futures.as_completed(futures):
        src, res = f.result()
        results[src] = res

# Print results
print("\n=== INTERNET REACHABILITY ===")
for src in sorted(results):
    for ip in INTERNET:
        status = "PASS" if results[src].get(ip) else "FAIL"
        print(f"  {src} -> {ip}: {status}")

print("\n=== NON-GUEST TO NON-GUEST (should all PASS) ===")
fails = []
passes = 0
for src in sorted(NON_GUEST):
    for dst in sorted(NON_GUEST):
        if dst == src:
            continue
        dst_ip = HOSTS[dst]["lab_ip"]
        if results[src].get(dst_ip):
            passes += 1
        else:
            fails.append(f"  {src} -> {dst} ({dst_ip}): FAIL")
print(f"  {passes} pairs PASS")
if fails:
    print("  FAILURES:")
    for f in fails:
        print(f)

print("\n=== GUEST TO GUEST (should PASS) ===")
for src in GUEST:
    for dst in GUEST:
        if dst == src:
            continue
        dst_ip = HOSTS[dst]["lab_ip"]
        status = "PASS" if results[src].get(dst_ip) else "FAIL"
        print(f"  {src} -> {dst} ({dst_ip}): {status}")

print("\n=== GUEST <-> NON-GUEST (should all FAIL - policy) ===")
wrong_passes = []
correct_fails = 0
for src in GUEST:
    for dst in NON_GUEST:
        dst_ip = HOSTS[dst]["lab_ip"]
        if results[src].get(dst_ip):
            wrong_passes.append(f"  {src} -> {dst} ({dst_ip}): PASS (WRONG!)")
        else:
            correct_fails += 1
for src in NON_GUEST:
    for dst in GUEST:
        dst_ip = HOSTS[dst]["lab_ip"]
        if results[src].get(dst_ip):
            wrong_passes.append(f"  {src} -> {dst} ({dst_ip}): PASS (WRONG!)")
        else:
            correct_fails += 1
print(f"  {correct_fails} pairs correctly FAIL")
if wrong_passes:
    print("  INCORRECT PASSES:")
    for w in wrong_passes:
        print(w)
